SELECT MIN(1.0 - ("flow_overview"->'performance'->>'retry_count')::numeric / (("flow_overview"->'performance'->>'error_count')::numeric + 1.0)),
       MAX(1.0 - ("flow_overview"->'performance'->>'retry_count')::numeric / (("flow_overview"->'performance'->>'error_count')::numeric + 1.0))
FROM "DataFlow";

-- Check join through RiskManagement.flow_link -> DataFlow.RecordRegistry
SELECT COUNT(*) FROM "DataFlow" df
JOIN "RiskManagement" rm ON df."RecordRegistry" = rm."flow_link";

SELECT COUNT(*) FROM "RiskManagement" 
WHERE "risk_management_profile"->'assessment'->>'control_effectiveness_pct' != 'None'
  AND ("risk_management_profile"->'assessment'->>'risk_score')::numeric * (1.0 / NULLIF(("risk_management_profile"->'assessment'->>'control_effectiveness_pct')::numeric, 0)) > 0.7;

-- Check how many DataFlow records don't have a matching RiskManagement entry via DataProfile
SELECT COUNT(*) FROM "DataFlow" df
WHERE NOT EXISTS (
    SELECT 1 FROM "DataProfile" dp 
    WHERE df."RecordRegistry" = dp."Flow_Sign"
    AND EXISTS (
        SELECT 1 FROM "RiskManagement" rm WHERE dp."riskJoin" = rm."RISKTRACE"
    )
);
